/** A small independent minimum-and-bag oracle for the currently admitted dependent-join costing routes. */
class PackedIndependentPhysicalOracleTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI FIRST = VF.createIRI("urn:t:first");
	private static final IRI SECOND = VF.createIRI("urn:t:second");
	private static final Set<Route> CONTEXTUAL_ROUTES = Set.of(Route.CONTEXTUAL_FIRST, Route.CONTEXTUAL_SECOND);

	@ParameterizedTest
	@EnumSource(Prices.class)
	void smallerPrefixWithMoreTypedWorkLosesUnderIndependentPrices(Prices prices) {
		Model data = data();
		assertEquals(2, data.filter(null, FIRST, null).size());
		assertEquals(4, data.filter(null, SECOND, null).size());
		List<String> expectedBag = independentBag(data);
		assertEquals(List.of("s=urn:t:subject", "s=urn:t:subject"), expectedBag,
				"the independent relation join must retain projection duplicates");

		// Both orientations are legal dependent joins. Their combined singleton populations are below the
		// current hash-admission floor, which is a policy rather than a semantic restriction. The written
		// orientation is also declared as a third, independently priced route from isolated children. The planner
		// cannot price the written route from isolated work because the left prefix binds ?key, so only the two
		// contextual routes must reach a physical callback; the written route must still not be the cheaper one.
		// These are synthetic prices, not measured access work.
		List<Alternative> alternatives = List.of(
				new Alternative(Route.WRITTEN_ISOLATED, 2, new Work(10, 0, 2)),
				new Alternative(Route.CONTEXTUAL_FIRST, 2, new Work(2, 10, 2)),
				new Alternative(Route.CONTEXTUAL_SECOND, 4, new Work(6, 0, 2)));
		assertTrue(alternatives.get(1).prefixRows() < alternatives.get(2).prefixRows());
		assertTrue(alternatives.get(1).work().seeks() > alternatives.get(2).work().seeks());
		assertEquals(prices.writtenPrice, prices.price(alternatives.get(0).work()));
		assertEquals(prices.firstPrice, prices.price(alternatives.get(1).work()));
		assertEquals(prices.secondPrice, prices.price(alternatives.get(2).work()));
		Alternative optimum = alternatives.stream()
				.min(Comparator.comparingLong(candidate -> prices.price(candidate.work())))
				.orElseThrow();
		assertEquals(prices.expectedWinner, optimum.route());
		assertEquals(prices.expectedPrice, prices.price(optimum.work()));

		// Materialize each independently enumerated order and verify its entire projected bag before planning.
		for (Order order : Order.values()) {
			assertEquals(expectedBag, evaluate(data, projectSubject(join(order))),
					"legal order changed the independently evaluated result bag: " + order);
		}

		SyntheticCosts costs = new SyntheticCosts(prices);
		PackedPlanningResult result = PackedCascadesPlanner.optimize(join(Order.FIRST_THEN_SECOND),
				OptimizationGoal.root(), costs);

		assertTrue(result.exactComplete(), () -> "the small search was incomplete: " + result.completionStatus());
		assertEquals(2.0d, result.outputRows(), "both physical orders have the same complete logical output");
		assertTrue(costs.writtenLogicalQuotes > 0, "the written logical join must receive its known output rows");
		assertEquals(new Work(2, 0, 0), costs.leafQuotes.get(Order.FIRST_THEN_SECOND));
		assertEquals(new Work(4, 0, 0), costs.leafQuotes.get(Order.SECOND_THEN_FIRST));
		assertTrue(costs.physicalJoinQuotes.keySet().containsAll(CONTEXTUAL_ROUTES),
				() -> "both contextual costing routes must reach a physical callback: "
						+ costs.physicalJoinQuotes.keySet());
		assertEquals(Set.of("dependent-iteration"), costs.physicalImplementations,
				"the independent enumeration must cover every physical implementation actually quoted");
		for (Alternative alternative : alternatives) {
			if (CONTEXTUAL_ROUTES.contains(alternative.route())) {
				assertEquals(alternative.work(), costs.completeQuote(alternative.route()),
						"the planner must quote the independently declared typed work for " + alternative.route());
			}
		}
		Join selected = assertInstanceOf(Join.class, result.selectedPlan());
		assertEquals(optimum.route().order, selectedOrder(selected), selected::toString);
		assertEquals((double) prices.price(optimum.work()), result.totalCost(), selected::toString);
		assertTrue(result.decisionSummary().selectedCostInterval().available(),
				"the selected plan is priced by the contextual route that won");
		assertEquals(expectedBag, evaluate(data, projectSubject(selected)),
				"the materialized selected plan must preserve the independently evaluated bag");
	}

	/** Test-side units; this record does not use the planner's cost-composition or ranking code. */
	private record Work(long sequentialRows, long seeks, long resultRows) {
		Work plus(Work other) {
			return new Work(sequentialRows + other.sequentialRows, seeks + other.seeks, resultRows + other.resultRows);
		}

		Work times(long invocations) {
			return new Work(sequentialRows * invocations, seeks * invocations, resultRows * invocations);
		}
	}

	private record Alternative(Route route, int prefixRows, Work work) {
	}

	private enum Order {
		FIRST_THEN_SECOND,
		SECOND_THEN_FIRST
	}

	private enum Route {
		WRITTEN_ISOLATED(Order.FIRST_THEN_SECOND),
		CONTEXTUAL_FIRST(Order.FIRST_THEN_SECOND),
		CONTEXTUAL_SECOND(Order.SECOND_THEN_FIRST);

		private final Order order;

		Route(Order order) {
			this.order = order;
		}
	}

	private enum Prices {
		EXPENSIVE_SEEKS(1, 3, 12, 34, 8, Route.CONTEXTUAL_SECOND, 8),
		EXPENSIVE_SCANS(3, 1, 32, 18, 20, Route.CONTEXTUAL_FIRST, 18);

		private final int sequential;
		private final int seek;
		private final long writtenPrice;
		private final long firstPrice;
		private final long secondPrice;
		private final Route expectedWinner;
		private final long expectedPrice;

		Prices(int sequential, int seek, long writtenPrice, long firstPrice, long secondPrice, Route expectedWinner,
				long expectedPrice) {
			this.sequential = sequential;
			this.seek = seek;
			this.writtenPrice = writtenPrice;
			this.firstPrice = firstPrice;
			this.secondPrice = secondPrice;
			this.expectedWinner = expectedWinner;
			this.expectedPrice = expectedPrice;
		}

		private long price(Work work) {
			return sequential * work.sequentialRows() + seek * work.seeks() + work.resultRows();
		}
	}

	/** Supplies synthetic prices; these are not measurements of the in-memory model's actual accesses. */
	private static final class SyntheticCosts implements PackedCostModel {
		private final Prices prices;
		private final Map<Order, Work> leafQuotes = new EnumMap<>(Order.class);
		private final Map<Order, Work> extensionQuotes = new EnumMap<>(Order.class);
		private final Map<Route, Work> physicalJoinQuotes = new EnumMap<>(Route.class);
		private final Set<String> physicalImplementations = new HashSet<>();
		private int writtenLogicalQuotes;

		private SyntheticCosts(Prices prices) {
			this.prices = prices;
		}

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			if (!query.isStatementPattern(relationId)) {
				return Double.NaN;
			}
			if (FIRST.equals(query.statementPatternValue(relationId, 1))) {
				return 2.0d;
			}
			return SECOND.equals(query.statementPatternValue(relationId, 1)) ? 4.0d : Double.NaN;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			return new PackedCostSession() {
				@Override
				public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
					if (!query.isStatementPattern(relationId)) {
						return;
					}
					boolean first = FIRST.equals(query.statementPatternValue(relationId, 1));
					double rows = first ? 2.0d : 4.0d;
					output.setRows(rows, rows);
					output.setInclusivePhysicalCost(rows, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
							0.0d, 0.0d);
					leafQuotes.put(first ? Order.FIRST_THEN_SECOND : Order.SECOND_THEN_FIRST, work(output));
				}

				@Override
				public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
					if (context.prefixRelationCount() != 1 || !query.isStatementPattern(relationId)) {
						return;
					}
					Order order = orderOfPrefix(query, context);
					boolean appendingSecond = SECOND.equals(query.statementPatternValue(relationId, 1));
					assertEquals(order == Order.FIRST_THEN_SECOND, appendingSecond);
					assertEquals(appendingSecond ? 2.0d : 4.0d, context.prefixRows());
					output.setContextualRows(2.0d, 0.0d);
					output.setLocalPhysicalCost(appendingSecond ? 0.0d : 2.0d, appendingSecond ? 10.0d : 0.0d,
							0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
					// The declared vector covers the complete supplied prefix, not one independent reopen.
					output.setInvocations(context.prefixRows());
					extensionQuotes.put(order, work(output));
				}

				@Override
				public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					if (query.operatorTag(relationId) == PackedRelOp.JOIN && context.prefixRelationCount() == 0) {
						// The full logical join cardinality is known independently from the fixture's data.
						output.setOutputRowsPreservingPhysicalCost(2.0d);
						writtenLogicalQuotes++;
					}
				}

				@Override
				public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
					String implementation = output.plannedStringMetric("optimizer.physicalJoinImplementation");
					if (context.prefixRelationCount() == 1 && implementation != null) {
						physicalImplementations.add(implementation);
						if ("dependent-iteration".equals(implementation)) {
							Order order = orderOfPrefix(query, context);
							Route route;
							if (order == Order.FIRST_THEN_SECOND && output.invocations() == 2.0d) {
								// The isolated RHS quote is reopened once for each of the two left rows.
								route = Route.WRITTEN_ISOLATED;
							} else {
								assertEquals(1.0d, output.invocations(), "contextual work already covers its prefix");
								route = order == Order.FIRST_THEN_SECOND
										? Route.CONTEXTUAL_FIRST
										: Route.CONTEXTUAL_SECOND;
							}
							physicalJoinQuotes.put(route, work(output));
						}
					}
				}

				@Override
				public double objectiveScore(PackedCostEstimate estimate) {
					return prices.sequential * estimate.sequentialRows() + prices.seek * estimate.randomSeeks()
							+ estimate.resultRows();
				}
			};
		}

		private Work completeQuote(Route route) {
			Work leaf = leafQuotes.get(route.order);
			Work extension = route == Route.WRITTEN_ISOLATED
					? leafQuotes.get(Order.SECOND_THEN_FIRST).times(2)
					: extensionQuotes.get(route.order);
			Work physicalJoin = physicalJoinQuotes.get(route);
			assertTrue(leaf != null && extension != null && physicalJoin != null,
					() -> "missing actual leaf, prefix, or physical quote for " + route + ": " + leafQuotes + ", "
							+ extensionQuotes + ", " + physicalJoinQuotes);
			return leaf.plus(extension).plus(physicalJoin);
		}
	}

	private static Work work(PackedCostEstimate estimate) {
		assertTrue(Double.isFinite(estimate.sequentialRows()));
		assertTrue(Double.isFinite(estimate.randomSeeks()));
		assertTrue(Double.isFinite(estimate.resultRows()));
		assertEquals(Math.rint(estimate.sequentialRows()), estimate.sequentialRows());
		assertEquals(Math.rint(estimate.randomSeeks()), estimate.randomSeeks());
		assertEquals(Math.rint(estimate.resultRows()), estimate.resultRows());
		assertEquals(0.0d, estimate.iteratorOpens());
		assertEquals(0.0d, estimate.expressionEvaluations());
		assertEquals(0.0d, estimate.hashBuildRows());
		assertEquals(0.0d, estimate.hashProbeRows());
		assertEquals(0.0d, estimate.pathExpansions());
		assertEquals(0.0d, estimate.remoteCalls());
		assertEquals(0.0d, estimate.peakMemoryRows());
		return new Work((long) estimate.sequentialRows(), (long) estimate.randomSeeks(), (long) estimate.resultRows());
	}

	private static Order orderOfPrefix(PackedQueryView query, PackedCostContext context) {
		int firstRelation = context.prefixRelationId(0);
		assertTrue(query.isStatementPattern(firstRelation));
		assertTrue(FIRST.equals(query.statementPatternValue(firstRelation, 1))
				|| SECOND.equals(query.statementPatternValue(firstRelation, 1)));
		return FIRST.equals(query.statementPatternValue(firstRelation, 1))
				? Order.FIRST_THEN_SECOND
				: Order.SECOND_THEN_FIRST;
	}

	private static Order selectedOrder(Join join) {
		StatementPattern left = assertInstanceOf(StatementPattern.class, join.getLeftArg());
		StatementPattern right = assertInstanceOf(StatementPattern.class, join.getRightArg());
		IRI leftPredicate = (IRI) left.getPredicateVar().getValue();
		IRI rightPredicate = (IRI) right.getPredicateVar().getValue();
		assertTrue(FIRST.equals(leftPredicate) && SECOND.equals(rightPredicate)
				|| SECOND.equals(leftPredicate) && FIRST.equals(rightPredicate), join::toString);
		return FIRST.equals(leftPredicate) ? Order.FIRST_THEN_SECOND : Order.SECOND_THEN_FIRST;
	}

	private static Join join(Order order) {
		StatementPattern first = new StatementPattern(Var.of("s"), Var.of("_first", FIRST, true, true),
				Var.of("key"));
		StatementPattern second = new StatementPattern(Var.of("key"), Var.of("_second", SECOND, true, true),
				Var.of("o"));
		return order == Order.FIRST_THEN_SECOND ? new Join(first, second) : new Join(second, first);
	}

	private static TupleExpr projectSubject(TupleExpr input) {
		return new Projection(input.clone(), new ProjectionElemList(new ProjectionElem("s")));
	}

	private static Model data() {
		Model data = new LinkedHashModel();
		data.add(VF.createIRI("urn:t:subject"), FIRST, VF.createIRI("urn:t:key0"));
		data.add(VF.createIRI("urn:t:subject"), FIRST, VF.createIRI("urn:t:unmatched"));
		data.add(VF.createIRI("urn:t:key0"), SECOND, VF.createIRI("urn:t:object0"));
		data.add(VF.createIRI("urn:t:key0"), SECOND, VF.createIRI("urn:t:object1"));
		data.add(VF.createIRI("urn:t:key1"), SECOND, VF.createIRI("urn:t:object2"));
		data.add(VF.createIRI("urn:t:key2"), SECOND, VF.createIRI("urn:t:object3"));
		return data;
	}

	/** A tiny relational evaluator independent of the optimizer and of the tuple-evaluation strategy. */
	private static List<String> independentBag(Model data) {
		List<String> rows = new ArrayList<>();
		for (Statement first : data.filter(null, FIRST, null)) {
			if (first.getObject() instanceof Resource key) {
				for (Statement ignored : data.filter(key, SECOND, null)) {
					rows.add("s=" + first.getSubject());
				}
			}
		}
		Collections.sort(rows);
		return rows;
	}
}
